// Pure send planner for the habit-tracking assistant.
// No clock, no file access, no mutation of arguments.

const HOUR_MS = 60 * 60 * 1000;
const WINDOW_24H_MS = 24 * HOUR_MS;
const DEDUPE_MS = 7 * 24 * HOUR_MS;
const CAP_24H = 3; // reminders + promos together

const CATEGORY_RANK = { critical: 0, reminder: 1, promo: 2 };

// Rule identifiers (one per reason).
export const RULES = Object.freeze({
  INVALID_CANDIDATE: 'invalid-candidate',
  PROMO_NOT_OPTED_IN: 'promo-not-opted-in',
  INVALID_USER_CONFIG: 'invalid-user-config',
  QUIET_HOURS: 'quiet-hours',
  DEDUPE_7_DAYS: 'dedupe-7-days',
  DEDUPE_IN_BATCH: 'dedupe-in-batch',
  CAP_24H: 'cap-3-per-24h',
});

function parseHHMM(value) {
  if (typeof value !== 'string') return null;
  const m = /^([01]\d|2[0-3]):([0-5]\d)$/.exec(value);
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
}

// Minutes since local midnight in `timeZone`, or null if the zone is invalid.
function localMinutes(timeZone, now) {
  try {
    const parts = new Intl.DateTimeFormat('en-US', {
      timeZone,
      hourCycle: 'h23',
      hour: '2-digit',
      minute: '2-digit',
    }).formatToParts(now);
    const hour = Number(parts.find((p) => p.type === 'hour').value);
    const minute = Number(parts.find((p) => p.type === 'minute').value);
    return hour * 60 + minute;
  } catch {
    return null;
  }
}

// Returns 'in' | 'out' | 'invalid'. Window is [start, end) and may wrap midnight.
// start === end is an empty window (nothing is quiet).
function quietHoursState(user, now) {
  const q = user.quietHours;
  if (q == null) return 'out';
  const start = parseHHMM(q.start);
  const end = parseHHMM(q.end);
  if (start === null || end === null) return 'invalid';
  const minutes = localMinutes(user.timeZone, now);
  if (minutes === null) return 'invalid';
  if (start === end) return 'out';
  const inside = start < end ? minutes >= start && minutes < end : minutes >= start || minutes < end;
  return inside ? 'in' : 'out';
}

export function planSends({ user, candidates, history, now }) {
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
    throw new TypeError('now must be a valid Date');
  }
  const nowMs = now.getTime();

  // Read history. An unparseable sentAt is treated as "just now" (fail closed).
  const sent = history.map((h) => {
    const t = Date.parse(h.sentAt);
    return { ms: Number.isNaN(t) ? nowMs : t, category: h.category, dedupeKey: h.dedupeKey };
  });

  const blockedKeys = new Set(
    sent.filter((h) => nowMs - h.ms < DEDUPE_MS).map((h) => h.dedupeKey),
  );
  const capUsed = sent.filter(
    (h) => (h.category === 'reminder' || h.category === 'promo') && nowMs - h.ms < WINDOW_24H_MS,
  ).length;
  let capLeft = Math.max(0, CAP_24H - capUsed);

  const quiet = quietHoursState(user, now); // only computed once, same for all candidates

  const droppedById = new Map(); // index -> rule
  const eligible = [];

  candidates.forEach((c, index) => {
    const reject = (rule) => droppedById.set(index, rule);
    if (!(c.category in CATEGORY_RANK) || !Number.isFinite(c.priority)) {
      return reject(RULES.INVALID_CANDIDATE);
    }
    // Apple App Store Review Guideline 4.5.4: no promotional push without opt-in.
    if (c.category === 'promo' && user.promoOptIn !== true) return reject(RULES.PROMO_NOT_OPTED_IN);
    // Critical alerts (fraud, account security) ignore quiet hours and the 24h cap.
    if (c.category !== 'critical') {
      if (quiet === 'invalid') return reject(RULES.INVALID_USER_CONFIG);
      if (quiet === 'in') return reject(RULES.QUIET_HOURS);
    }
    if (blockedKeys.has(c.dedupeKey)) return reject(RULES.DEDUPE_7_DAYS);
    eligible.push({ c, index });
  });

  // Best first: priority desc, then critical > reminder > promo, then input order.
  eligible.sort(
    (a, b) =>
      b.c.priority - a.c.priority ||
      CATEGORY_RANK[a.c.category] - CATEGORY_RANK[b.c.category] ||
      a.index - b.index,
  );

  const send = [];
  const claimed = new Set();
  for (const { c, index } of eligible) {
    if (claimed.has(c.dedupeKey)) {
      droppedById.set(index, RULES.DEDUPE_IN_BATCH);
      continue;
    }
    if (c.category !== 'critical') {
      if (capLeft <= 0) {
        droppedById.set(index, RULES.CAP_24H);
        continue;
      }
      capLeft -= 1;
    }
    claimed.add(c.dedupeKey);
    send.push(c.id);
  }

  const dropped = [];
  candidates.forEach((c, index) => {
    if (droppedById.has(index)) dropped.push({ id: c.id, rule: droppedById.get(index) });
  });
  return { send, dropped };
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { planSends } from './bot.mjs';

const now = new Date('2026-10-23T18:00:00Z'); // 13:00 Chicago (CDT), 14:00 New York
const user = { timeZone: 'America/Chicago', promoOptIn: true, quietHours: null };
const c = (id, category, priority, dedupeKey = id) => ({ id, category, priority, dedupeKey });
const h = (hoursAgo, category, dedupeKey) => ({
  sentAt: new Date(now.getTime() - hoursAgo * 3600e3).toISOString(),
  category,
  dedupeKey,
});
const plan = (over) => planSends({ user, candidates: [], history: [], now, ...over });

test('orders by priority and drops over the 3 per 24h cap', () => {
  const r = plan({
    candidates: [c('a', 'reminder', 1), c('b', 'promo', 5), c('c', 'reminder', 3), c('d', 'reminder', 2)],
  });
  assert.deepEqual(r.send, ['b', 'c', 'd']);
  assert.deepEqual(r.dropped, [{ id: 'a', rule: 'cap-3-per-24h' }]);
});

test('history counts toward the rolling cap; 24h boundary is outside', () => {
  const history = [h(1, 'promo', 'x'), h(23.9, 'reminder', 'y'), h(24, 'reminder', 'z'), h(2, 'critical', 'w')];
  const r = plan({ history, candidates: [c('a', 'reminder', 2), c('b', 'reminder', 1)] });
  assert.deepEqual(r.send, ['a']);
  assert.deepEqual(r.dropped, [{ id: 'b', rule: 'cap-3-per-24h' }]);
});

test('critical ignores cap, quiet hours, and does not consume the cap', () => {
  const u = { ...user, quietHours: { start: '12:00', end: '14:00' } };
  const history = [h(1, 'promo', 'x'), h(2, 'promo', 'y'), h(3, 'promo', 'z')];
  const r = planSends({
    user: u, history, now,
    candidates: [c('crit', 'critical', 1), c('rem', 'reminder', 9)],
  });
  assert.deepEqual(r.send, ['crit']);
  assert.deepEqual(r.dropped, [{ id: 'rem', rule: 'quiet-hours' }]);
  const r2 = plan({ history, candidates: [c('crit', 'critical', 1), c('rem', 'reminder', 9)] });
  assert.deepEqual(r2.send, ['crit']);
  assert.equal(r2.dropped[0].rule, 'cap-3-per-24h');
});

test('promo without opt-in is dropped, critical and reminder unaffected', () => {
  const r = planSends({
    user: { ...user, promoOptIn: false }, history: [], now,
    candidates: [c('p', 'promo', 9), c('r', 'reminder', 1)],
  });
  assert.deepEqual(r.send, ['r']);
  assert.deepEqual(r.dropped, [{ id: 'p', rule: 'promo-not-opted-in' }]);
});

test('quiet hours use the user time zone and wrap midnight', () => {
  const q = { ...user, quietHours: { start: '22:00', end: '07:00' } };
  const at = (iso) => planSends({ user: q, history: [], now: new Date(iso), candidates: [c('r', 'reminder', 1)] });
  assert.equal(at('2026-10-24T03:30:00Z').dropped[0]?.rule, 'quiet-hours'); // 22:30 Chicago
  assert.equal(at('2026-10-24T12:00:00Z').dropped[0]?.rule, 'quiet-hours'); // 07:00 UTC-5? 07:00 CDT = 12:00Z -> end is exclusive
  assert.deepEqual(at('2026-10-24T12:00:00Z').send, ['r']);
  assert.deepEqual(at('2026-10-24T20:00:00Z').send, ['r']); // 15:00 Chicago
});

test('7-day dedupe against history and inside the batch', () => {
  const history = [h(24 * 6.9, 'reminder', 'k'), h(24 * 7, 'reminder', 'old')];
  const r = plan({
    history,
    candidates: [c('a', 'reminder', 1, 'k'), c('b', 'reminder', 2, 'old'), c('c', 'reminder', 3, 'old')],
  });
  assert.deepEqual(r.send, ['c']);
  assert.deepEqual(r.dropped, [
    { id: 'a', rule: 'dedupe-7-days' },
    { id: 'b', rule: 'dedupe-in-batch' },
  ]);
});

test('does not mutate arguments', () => {
  const args = {
    user: { ...user, quietHours: { start: '01:00', end: '02:00' } },
    candidates: [c('a', 'reminder', 1), c('b', 'reminder', 2)],
    history: [h(1, 'promo', 'x')],
    now,
  };
  const snap = structuredClone({ ...args, now: now.getTime() });
  planSends(args);
  assert.deepEqual(structuredClone({ ...args, now: args.now.getTime() }), snap);
});

test('every candidate is in send or dropped exactly once', () => {
  const cs = [c('a', 'promo', 1), c('b', 'bogus', 1), c('d', 'reminder', NaN), c('e', 'critical', 0)];
  const r = plan({ candidates: cs });
  assert.deepEqual([...r.send, ...r.dropped.map((d) => d.id)].sort(), ['a', 'b', 'd', 'e']);
});
